async function loadUser(id) {
  const res = await fetch(`/api/users/${id}`);
  const data = res.json();
  return data.name;
}

**Bug:** `res.json()` returns a Promise, and it's missing an `await`. So `data` is a Promise and `data.name` is `undefined`.

**Next most important:** `fetch` only rejects on network failure. A 404 or 500 still resolves, so check `res.ok` before parsing.

```js
async function loadUser(id) {
  const res = await fetch(`/api/users/${encodeURIComponent(id)}`);
  if (!res.ok) {
    throw new Error(`loadUser ${id}: HTTP ${res.status}`);
  }
  const data = await res.json();
  return data.name;
}
```

**Minor:** `encodeURIComponent` protects the URL if an id ever contains `/` or `?`. It's harmless for numeric ids.

